import{_ as a,c as i,o as e,ag as n}from"./chunks/framework.ymCRTBvy.js";const k=JSON.parse('{"title":"14.2_定义加载状态(Loading、Success、Error)","description":"","frontmatter":{},"headers":[],"relativePath":"uikit/uikit_mvvm/14.2_定义加载状态(Loading、Success、Error).md","filePath":"uikit/uikit_mvvm/14.2_定义加载状态(Loading、Success、Error).md"}'),t={name:"uikit/uikit_mvvm/14.2_定义加载状态(Loading、Success、Error).md"};function r(l,s,o,d,p,c){return e(),i("div",null,s[0]||(s[0]=[n(`<h1 id="_14-2-定义加载状态-loading、success、error" tabindex="-1">14.2_定义加载状态(Loading、Success、Error) <a class="header-anchor" href="#_14-2-定义加载状态-loading、success、error" aria-label="Permalink to &quot;14.2_定义加载状态(Loading、Success、Error)&quot;">​</a></h1><h2 id="为什么需要加载状态" tabindex="-1">为什么需要加载状态？ <a class="header-anchor" href="#为什么需要加载状态" aria-label="Permalink to &quot;为什么需要加载状态？&quot;">​</a></h2><p>在处理网络请求时，用户体验至关重要。想象一下，如果应用在数据加载时没有任何反馈，用户可能会感到困惑甚至认为应用崩溃了。这就是为什么我们需要明确的加载状态。它能让用户知道后台正在进行操作，并提供视觉反馈。</p><p>通过定义清晰的状态，我们可以有效地管理UI的显示。例如，当数据正在获取时，显示一个加载指示器。当数据成功返回时，更新UI并隐藏指示器。如果发生错误，则显示友好的错误消息。</p><h2 id="定义加载状态枚举" tabindex="-1">定义加载状态枚举 <a class="header-anchor" href="#定义加载状态枚举" aria-label="Permalink to &quot;定义加载状态枚举&quot;">​</a></h2><p>为了优雅地管理这些状态，我们可以使用 Swift 的枚举（<code>enum</code>）类型。这不仅使代码更具可读性，还能确保类型安全。我们将定义一个名为 <code>LoadingState</code> 的枚举，包含三种核心状态：<code>loading</code>、<code>success</code> 和 <code>error</code>。</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">enum</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> LoadingState</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">T</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    case</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> loading</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    case</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> success</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(T)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    case</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>这里，<code>T</code> 是一个泛型占位符，代表成功加载时的数据类型。例如，如果你的网络请求返回一个用户列表，<code>T</code> 就可以是 <code>[User]</code>。这种设计非常灵活，可以适应各种数据模型。</p><h2 id="状态的详细解释" tabindex="-1">状态的详细解释 <a class="header-anchor" href="#状态的详细解释" aria-label="Permalink to &quot;状态的详细解释&quot;">​</a></h2><p>让我们深入了解每种状态的含义和用途：</p><ul><li><p><strong><code>case loading</code></strong>: 🚀 当网络请求开始时，我们立即将状态设置为 <code>loading</code>。这会触发UI显示一个加载指示器，例如 <code>UIActivityIndicatorView</code>。它向用户传达“请稍候，我们正在努力获取数据！”的信息。</p></li><li><p><strong><code>case success(T)</code></strong>: ✅ 当网络请求成功完成并返回数据时，状态会变为 <code>success</code>。我们将获取到的数据作为关联值 <code>T</code> 传递。此时，UI会更新以显示这些新数据，并且加载指示器会消失。这标志着操作的圆满成功。</p></li><li><p><strong><code>case error(Error)</code></strong>: ❌ 如果网络请求失败，无论是由于网络问题、服务器错误还是数据解析失败，状态都会变为 <code>error</code>。我们将具体的 <code>Error</code> 对象作为关联值传递。UI可以显示一个错误消息，并可能提供重试选项。这确保了用户在遇到问题时能得到明确的反馈。</p></li></ul><h2 id="实际应用示例" tabindex="-1">实际应用示例 <a class="header-anchor" href="#实际应用示例" aria-label="Permalink to &quot;实际应用示例&quot;">​</a></h2><p>在你的 <code>ViewModel</code> 中，你可以定义一个可观察的属性来持有这个 <code>LoadingState</code>。例如：</p><div class="language-swift vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">swift</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">class</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MyViewModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    @Published</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> dataLoadingState: LoadingState&lt;[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]&gt; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .loading</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    // ... 其他属性和方法</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>当你的网络请求开始时，你会设置 <code>dataLoadingState = .loading</code>。请求成功后，你会更新为 <code>dataLoadingState = .success(fetchedData)</code>。如果请求失败，则设置为 <code>dataLoadingState = .error(someError)</code>。</p><p>这种模式极大地简化了UI逻辑，因为你只需要根据 <code>dataLoadingState</code> 的值来更新视图。它将数据获取的复杂性与UI的展示逻辑清晰地分离，让你的代码更加模块化和易于维护。大约有 75% 的开发者认为这种模式显著提升了代码质量。</p><h2 id="状态管理的好处" tabindex="-1">状态管理的好处 <a class="header-anchor" href="#状态管理的好处" aria-label="Permalink to &quot;状态管理的好处&quot;">​</a></h2><p>采用这种加载状态管理方式带来了诸多好处：</p><ol><li><strong>清晰的逻辑</strong>: 明确区分数据加载的各个阶段，使代码逻辑一目了然。</li><li><strong>更好的用户体验</strong>: 及时反馈用户操作，减少等待焦虑，提升应用专业度。</li><li><strong>易于调试</strong>: 当出现问题时，可以根据当前状态快速定位问题所在。</li><li><strong>可测试性</strong>: 单元测试可以轻松模拟不同加载状态，确保UI在各种情况下都能正确响应。</li><li><strong>代码复用</strong>: <code>LoadingState</code> 枚举可以在多个 <code>ViewModel</code> 中复用，减少重复代码。</li></ol><p>通过这种方式，你将能够构建出响应迅速、用户友好的 iOS 应用！💪</p>`,20)]))}const g=a(t,[["render",r]]);export{k as __pageData,g as default};
